    #[test]
    fn authenticate(){

        for v in VECTORS{
            let vector = AuthVectors::from_str(v);
            let k: Key = vector.key.into();
            let ctx = CryptoContext::new(k);
            let tag = ctx.authenticate(&vector.nodeid, &vector.timestamp, &vector.payload);
            assert_eq!(tag, vector.tag);
        }

    }

    #[test]
    fn encrypt_authenticate(){

        for v in VECTORS{
            let vector = AuthVectors::from_str(v);
            let k: Key = vector.key.into();
            let ctx = CryptoContext::new(k);
            let mut pld = vector.payload.clone();

            let tag = ctx.encrypt_and_authenticate(&vector.nodeid, &vector.timestamp, &mut pld);
            assert_eq!(tag, vector.tag);
            assert_eq!(pld, vector.enc_payload);
        }

    }

    #[test]
    fn verify(){
        for v in VECTORS{
            let vector = AuthVectors::from_str(v);
            let k: Key = vector.key.into();
            let ctx = CryptoContext::new(k);
            assert!(ctx.verify(&vector.nodeid, &vector.timestamp, &vector.payload, &vector.tag));
        }

    }

    #[test]
    fn decrypt_verify(){

        for v in VECTORS{
            let vector = AuthVectors::from_str(v);
            let k: Key = vector.key.into();
            let ctx = CryptoContext::new(k);
            let mut pld = vector.enc_payload.clone();

            assert!(ctx.decrypt_and_verify(&vector.nodeid, &vector.timestamp, &mut pld, &vector.tag));
            assert_eq!(pld, vector.payload);
        }

    }

